# m2a: convert MIT format annotation files to AHA DB distribution tape
# format.
#
# The files generated by this program are in the format formerly used for
# distribution of the AHA and MIT-BIH databases on half-inch 9-track digital
# tape. It does *not* generate files in the format currently used for
# distribution of the AHA database on floppy disk; a2m can perform the
# reverse conversion, however.
#
# This file is part of wfdb-x, an independent reimplementation of the WFDB
# Software Package in Python, C++, MATLAB/Octave, Rust, Julia, R and Kotlin.
#
# It is a Julia translation of convert/m2a.c from the WFDB Software Package
# 10.7.0, by George B. Moody. The translation follows the logic and behavior of
# the original program, but it is new code, not the original C code.
#
# Changes from the original: no built-in sampling frequency: the new option -F
# FREQ gives it when the record header gives none, and is then required for -s
# (the original assumed 250 Hz); --legacy, as the first argument, restores the
# original behavior. Each change is marked "wfdb-x:" in the code;
# docs/DIVERGENCES.md gives the reasons.
#
# Original C program: convert/m2a.c, WFDB Software Package 10.7.0.
#   Copyright (C) 2001 George B. Moody.
# Julia translation and changes: Copyright (C) 2026 Reza Sameni.
#
# This program is free software: you can redistribute it and/or modify it
# under the terms of the GNU General Public License as published by the Free
# Software Foundation, either version 3 of the License, or (at your option)
# any later version. See LICENSE.

const _M2A_HELP = (
    "usage: %s -r RECORD -a MIT-ANNOTATOR AHA-ANNOTATOR [ OPTIONS ... ]\n",
    "where RECORD is the record name, MIT-ANNOTATOR is the annotator name",
    "for the input annotation file, AHA-ANNOTATOR is the annotator name",
    "for the output (AHA format) annotation file, and OPTIONS may include:",
    " -F FREQ   sampling frequency, if the record header does not specify one",
    " -h        print this usage summary",
    " -s TIME   shift annotation times backwards by the specified TIME,",
    "            and convert them to milliseconds")
# wfdb-x: the help text of the original program, printed in legacy mode
const _M2A_LEGACY_HELP = _help_without(_M2A_HELP, 5)

const _M2A_MS_PER_S = 1000.0    # milliseconds per second

function m2a_main(args::Vector{String})
    # wfdb-x: --legacy as the first argument selects legacy mode (the
    # behavior of the original program; see wfdbx_legacy_args)
    legacy = wfdbx_legacy_args(args) != 0
    argv = cargs(args)              # C argv[i] (i >= 1) is argv[i]
    argc = length(argv) + 1
    pname = "m2a"
    ianame = oaname = record = shift = nothing
    annot = Annotation()
    ffreq = 0.0

    i = 1
    while i < argc
        a = argv[i]
        if _annapp_c0(a) == UInt8('-')
            c = _annapp_c1(a)
            if c == UInt8('a')          # annotator names follow
                i += 1
                if i + 1 >= argc
                    ceprintf("%s: input and output annotator names must follow -a\n", pname)
                    cexit(1)
                end
                ianame = argv[i]
                i += 1
                oaname = argv[i]
            elseif c == UInt8('F') && !legacy   # sampling frequency follows (wfdb-x)
                i += 1
                ffreq = _annapp_ffreq(pname, argv, i, argc)
            elseif c == UInt8('h')      # help requested
                _annapp_help(pname, legacy ? _M2A_LEGACY_HELP : _M2A_HELP)
                cexit(1)
            elseif c == UInt8('r')      # record name follows
                i += 1
                if i >= argc
                    ceprintf("%s: record name must follow -r\n", pname)
                    cexit(1)
                end
                record = argv[i]
            elseif c == UInt8('s')      # shift follows
                i += 1
                if i >= argc
                    ceprintf("%s: time shift must follow -s\n", pname)
                    cexit(1)
                end
                shift = argv[i]
            else
                ceprintf("%s: unrecognized option %s\n", pname, a)
                cexit(1)
            end
        else
            ceprintf("%s: unrecognized argument %s\n", pname, a)
            cexit(1)
        end
        i += 1
    end
    if ianame === nothing || oaname === nothing || record === nothing
        _annapp_help(pname, legacy ? _M2A_LEGACY_HELP : _M2A_HELP)
        cexit(1)
    end

    afarray = [Anninfo(ianame, WFDB_READ), Anninfo(oaname, WFDB_AHA_WRITE)]
    annopen(record, afarray, 2) < 0 && cexit(2)     # open files
    if shift === nothing
        while getann(0, annot) >= 0         # copy annotations to end of data
            putann(0, annot)
        end
    else
        # wfdb-x: no default sampling frequency (the C program assumed 250 Hz
        # if the record header did not specify one, as legacy mode does); -F
        # specifies one.
        if sampfreq(record) <= 0.0
            if legacy
                setsampfreq(WFDB_DEFFREQ)
            elseif ffreq > 0.0
                setsampfreq(ffreq)
            else
                _annapp_nofreq(pname, record)
            end
        end
        mssi = _M2A_MS_PER_S / Float64(strtim("1"))     # milliseconds per sample interval
        dt = strtim(shift)
        while getann(0, annot) >= 0
            if annot.time >= dt
                annot.time = d2l(Float64(annot.time - dt) * mssi)
                putann(0, annot)
            end
        end
    end

    wfdbquit()
    cexit(0)
end

register_workload("m2a") do
    with_workload_data() do dir
        workload_tool("m2a", "-r", "100s", "-a", "atr", "aha2")
        workload_tool("m2a", "-r", "100s", "-a", "atr", "aha2", "-s", "0:5")
        workload_tool("m2a", "-r", "100s", "-a", "nosuch", "aha2")
        workload_tool("m2a", "-r", "100s", "-a", "atr")
        workload_tool("m2a", "-h")
        workload_tool("m2a", "-q")
        workload_tool("m2a", "x")
    end
    with_workload_data(files=NODEFAULTS_FILES) do dir
        cp("100s.atr", "nh.atr")
        workload_tool("m2a", "-r", "nh", "-a", "atr", "aha", "-s", "1")
        workload_tool("m2a", "-r", "nh", "-a", "atr", "aha", "-s", "1", "-F", "250")
        workload_tool("m2a", "-r", "nh", "-a", "atr", "aha", "-F", "-1")
        # wfdb-x: legacy mode (original behavior)
        workload_tool("m2a", "--legacy", "-r", "nh", "-a", "atr", "aha", "-s", "1")
        workload_tool("m2a", "--legacy", "-r", "nh", "-a", "atr", "aha", "-F", "250")
        workload_tool("m2a", "--legacy", "-h")
    end
end
